head.script:
scwin.onpageload = function() {
    textbox1.setValue($p.id + "textbox1");
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. main 샘플을 실행 후 UI의 결과 값을 확인한다.
    //1. Run the main sample and check the result of the UI.
    //Verify step 1. Textbox1, w1_textbox1, and w2_textbox1 values are displayed (no value is shown before the function is added)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#textbox1').text() == $p.id+'textbox1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#w1_textbox1').text() == $p.id+'w1_textbox1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#w2_textbox1').text() == $p.id+'w2_textbox1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 06-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
